	// evaluates to "hello world"
	String helloWorld = parser.parseExpression("'hello' + ' ' + 'world'")
			.getValue(String.class);

	// -- Character Subtraction --

	// evaluates to 'a'
	char ch = parser.parseExpression("'d' - 3")
			.getValue(char.class);

	// -- Repeat --

	// evaluates to "abcabc"
	String repeated = parser.parseExpression("'abc' * 2")
			.getValue(String.class);
